import React, { useCallback, useEffect, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import {
  FiArrowLeft,
  FiTrash2,
  FiPlus
} from "react-icons/fi";

import DashboardLayout from "../../layouts/DashboardLayout";
import Card from "../../components/Card";
import DataTable from "../../components/DataTable";
import ConfirmDialog from "../../components/ConfirmDialog";
import Loading from "../../components/Loading";
import StatusBadge from "../../components/StatusBadge";

import { studentApi } from "../../api/studentApi";
import { registrationApi } from "../../api/registrationApi";

import { useToast } from "../../context/ToastContext";
import { extractErrorMessage } from "../../api/axios";

import {
  fullName,
  formatDateTime
} from "../../utils/formatters";

export default function StudentCourses() {
  const { id } = useParams();
  const navigate = useNavigate();
  const toast = useToast();

  const [student, setStudent] = useState(null);
  const [courses, setCourses] = useState([]);

  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");

  const [dropTarget, setDropTarget] = useState(null);
  const [isDropping, setIsDropping] = useState(false);

  /*
   * =========================================================
   * LOAD STUDENT + REGISTERED COURSES
   * =========================================================
   */

  const loadData = useCallback(async () => {
    if (!id) {
      setError("Student ID is missing.");
      setIsLoading(false);
      return;
    }

    setIsLoading(true);
    setError("");

    try {
      /*
       * Load student
       */
      const studentResponse = await studentApi.getOne(id);

      const studentData = studentResponse?.data;

      let studentRecord = null;

      if (studentData?.student) {
        studentRecord = studentData.student;
      } else if (studentData?.data) {
        studentRecord = studentData.data;
      } else {
        studentRecord = studentData;
      }

      if (!studentRecord) {
        throw new Error("Student not found.");
      }

      setStudent(studentRecord);

      /*
       * Load registered courses
       */
      const coursesResponse =
        await registrationApi.getByStudent(id);

      const coursesData = coursesResponse?.data;

      let courseList = [];

      if (Array.isArray(coursesData)) {
        courseList = coursesData;
      } else if (Array.isArray(coursesData?.data)) {
        courseList = coursesData.data;
      } else if (Array.isArray(coursesData?.registrations)) {
        courseList = coursesData.registrations;
      } else if (Array.isArray(coursesData?.items)) {
        courseList = coursesData.items;
      }

      setCourses(courseList);
    } catch (err) {
      const message = extractErrorMessage(
        err,
        "Unable to load student courses."
      );

      setError(message);

      /*
       * Only show toast.
       * Do not automatically navigate away,
       * because navigating can contribute to
       * the page appearing to vibrate.
       */
      toast.error(message);
    } finally {
      setIsLoading(false);
    }
  }, [id, toast]);

  /*
   * =========================================================
   * LOAD WHEN STUDENT ID CHANGES
   * =========================================================
   */

  useEffect(() => {
    loadData();
  }, [loadData]);

  /*
   * =========================================================
   * DROP COURSE
   * =========================================================
   */

  async function confirmDrop() {
    if (!dropTarget) {
      return;
    }

    const registrationId =
      dropTarget.registration_id ??
      dropTarget.id;

    if (!registrationId) {
      toast.error(
        "Registration ID was not found."
      );
      return;
    }

    setIsDropping(true);

    try {
      await registrationApi.remove(registrationId);

      toast.success(
        "Course dropped successfully."
      );

      setDropTarget(null);

      await loadData();
    } catch (err) {
      toast.error(
        extractErrorMessage(
          err,
          "Unable to drop this course."
        )
      );
    } finally {
      setIsDropping(false);
    }
  }

  /*
   * =========================================================
   * TABLE COLUMNS
   * =========================================================
   */

  const columns = [
    {
      key: "course_code",
      label: "Course Code",
      render: (row) => {
        const code =
          row.course_code ??
          row.course?.course_code ??
          row.course?.code ??
          "—";

        return (
          <span className="font-mono text-xs bg-navy-50 text-navy-700 px-2 py-1 rounded">
            {code}
          </span>
        );
      }
    },

    {
      key: "course_name",
      label: "Course Name",
      render: (row) => {
        return (
          <span className="font-medium text-ink">
            {row.course_name ??
              row.course?.course_name ??
              row.course?.name ??
              "—"}
          </span>
        );
      }
    },

    {
      key: "credit_hour",
      label: "Credit Hour",
      render: (row) => {
        return (
          row.credit_hour ??
          row.course?.credit_hour ??
          "—"
        );
      },
      hideOnMobile: true
    },

    {
      key: "semester",
      label: "Semester",
      render: (row) => row.semester || "—"
    },

    {
      key: "academic_year",
      label: "Academic Year",
      render: (row) =>
        row.academic_year || "—",
      hideOnMobile: true
    },

    {
      key: "registered_at",
      label: "Registered At",
      render: (row) => {
        if (!row.registered_at) {
          return "—";
        }

        return formatDateTime(
          row.registered_at
        );
      },
      hideOnMobile: true
    },

    {
      key: "status",
      label: "Status",
      render: (row) => (
        <StatusBadge
          status={
            row.status ||
            "registered"
          }
        />
      )
    },

    {
      key: "actions",
      label: "Actions",
      render: (row) => (
        <button
          type="button"
          onClick={() => setDropTarget(row)}
          className="flex items-center gap-1.5 text-xs font-medium text-red-600 hover:bg-red-50 px-2.5 py-1.5 rounded-md"
        >
          <FiTrash2 size={13} />
          Drop
        </button>
      )
    }
  ];

  /*
   * =========================================================
   * LOADING
   * =========================================================
   */

  if (isLoading) {
    return (
      <DashboardLayout>
        <Loading label="Loading registered courses..." />
      </DashboardLayout>
    );
  }

  /*
   * =========================================================
   * PAGE
   * =========================================================
   */

  return (
    <DashboardLayout>

      {/* BACK BUTTON */}

      <Link
        to="/registrations"
        className="inline-flex items-center gap-1.5 text-sm text-navy-600 hover:text-navy-800 mb-4"
      >
        <FiArrowLeft size={14} />
        Back to Student Search
      </Link>

      {/* HEADER */}

      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">

        <div>

          <h1 className="font-display text-xl text-navy-800">
            {student
              ? fullName(student)
              : "Student"}
          </h1>

          {student?.registration_number && (
            <p className="text-sm text-muted font-mono">
              {student.registration_number}
            </p>
          )}

        </div>

        <Link
          to="/registrations/create"
          className="flex items-center gap-2 bg-navy-700 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-navy-800 transition"
        >
          <FiPlus size={15} />
          Register New Course
        </Link>

      </div>

      {/* ERROR */}

      {error && (
        <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          {error}
        </div>
      )}

      {/* COURSES TABLE */}

      <Card>

        <DataTable
          columns={columns}
          rows={courses}
          isLoading={false}
          error=""
          emptyTitle="No courses have been registered yet."
          emptyDescription="Register this student into a course to see it appear here."
          emptyAction={{
            label: "Register Course",
            onClick: () =>
              navigate("/registrations/create")
          }}
        />

      </Card>

      {/* DROP CONFIRMATION */}

      <ConfirmDialog
        isOpen={Boolean(dropTarget)}
        onClose={() => {
          if (!isDropping) {
            setDropTarget(null);
          }
        }}
        onConfirm={confirmDrop}
        isLoading={isDropping}
        title="Drop this course?"
        confirmLabel="Drop Course"
        itemLabel={
          dropTarget
            ? `${
                dropTarget.course_code ||
                dropTarget.course?.code ||
                dropTarget.course?.course_code ||
                "Course"
              } — ${
                dropTarget.course_name ||
                dropTarget.course?.name ||
                dropTarget.course?.course_name ||
                ""
              }`
            : ""
        }
        description="The student will be unregistered from this course. This action cannot be undone."
      />

    </DashboardLayout>
  );
}
